effect.frag.content:
uniform float u_amount;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return texture(u_source, uv);
}
void main() {
  vec2 uv = v_uv;
  float depth = 1.0;
  if (v_uv.y > 0.75) { depth = max(0.03, (1.0 - v_uv.y) / 0.25); uv = vec2(v_uv.x / depth, (v_uv.y - 0.75) / depth); }
  else if (v_uv.y < 0.25) { depth = max(0.03, v_uv.y / 0.25); uv = vec2(v_uv.x / depth, (0.25 - v_uv.y) / depth); }
  else uv.y = (v_uv.y - 0.25) * 2.0;
  uv.x = fract(uv.x * (1.0 + floor(u_amount * 3.0)) + u_progress);
  uv.y = fract(uv.y);
  vec4 c = sourceAt(uv); c.rgb *= 0.55 + depth * 0.45;
  fragColor = c;
}
